input.command:
cat > /tmp/probe/scratch/mpred.awk <<'EOF'
function pred(w,  n,c2,c1) {
  n=length(w); c1=substr(w,n,1); c2=substr(w,n-1,1);
  if (c1=="y" && n>1 && c2 !~ /[aeiou]/) return substr(w,1,n-1) "ies";
  if (substr(w,n-1,2)=="es") return w;
  if (c1=="s" || substr(w,n-1,2)=="ch" || substr(w,n-1,2)=="sh") return w "es";
  return w "s";
}
BEGIN{FS="\t"; OFS="\t"}
{ lw=tolower($1); p=pred(lw); if ($2 != p) print $1, $2, p }
EOF
awk -f /tmp/probe/scratch/mpred.awk /tmp/probe/data/common-nouns-m.tsv | sort -u > /tmp/probe/scratch/m_dev.tsv
wc -l /tmp/probe/scratch/m_dev.tsv; cat /tmp/probe/scratch/m_dev.tsv
